     1	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
     2	import { COUNTRIES, DEFAULT_COUNTRY_SLUG, type CountryConfig } from '../config/countries';
     3	
     4	type MultiSiteContext = {
     5	  site?: { id: string; alias?: string };
     6	  locale?: { id: string; preferredCurrency?: string };
     7	};
     8	
     9	/**
    10	 * Returns the full CountryConfig for the active SFCC site + locale.
    11	 *
    12	 * Matches on both sfccSiteId and locale to disambiguate the en-GB collision
    13	 * between the UK site ('gb') and EU English ('eu'). Falls back to AU when the
    14	 * site ID is unrecognised (e.g. during local dev before config/sites.js is wired up).
    15	 *
    16	 * @returns The CountryConfig for the current region, or the AU default.
    17	 */
    18	export function useCountryConfig(): CountryConfig {
    19	  const { site, locale } = useMultiSite() as MultiSiteContext;
    20	  const match = Object.values(COUNTRIES).find((c) => c.sfccSiteId === site?.id && c.locale === locale?.id);
    21	  return match ?? COUNTRIES[DEFAULT_COUNTRY_SLUG];
    22	}

